                return 998_244_353L;
            }
        }

        abstract static class Modulus<M extends Modulus<M>> {
            final java.util.Stack<Integer> factorial = new java.util.Stack<>();
            final java.util.Stack<Integer> invFactorial = new java.util.Stack<>();

            public abstract long modulus();

            public Modulus() {
                factorial.push(1);
                invFactorial.push(1);
            }

            public long fact(int n) {
                while (factorial.size() <= n) {
                    int last = factorial.peek();
                    factorial.push((int) mult(last, factorial.size()));
                }
                return factorial.get(n);
            }

            public long fInv(int n) {
                int lastIdx = invFactorial.size() - 1;
                if (lastIdx < n) {
                    long[] fInvArr = new long[n - lastIdx];
                    fInvArr[0] = inv(fact(n));
                    for (int i = 1; i < fInvArr.length; i++) {
                        fInvArr[i] = mult(fInvArr[i - 1], n - i + 1);
                    }
                    for (int i = fInvArr.length - 1; i >= 0; i--) {
                        invFactorial.push((int) fInvArr[i]);
                    }
                }
                return invFactorial.get(n);
            }

            public long ncr(int n, int r) {
                if (n < 0 || r < 0 || n < r)
                    return 0;
                return mult(fact(n), mult(fInv(r), fInv(n - r)));
            }

            public long smallInv(int n) {
                return mult(fInv(n), fact(n - 1));
            }

            public long normalize(long x) {
                long mod = modulus();
                x %= mod;
                if (x < 0) x += mod;
                return x;
            }

            public long add(long a, long b) {
                long res = a + b;
                long m = modulus();
                return res >= m ? res - m : res;
            }

            public long subtract(long a, long b) {
                long res = a - b;
                long m = modulus();
                return res < 0 ? res + m : res;
            }

            public long mult(long a, long b) {
                return (a * b) % modulus();
            }

            public long inv(long value) {
                long g = modulus(), x = 0, y = 1;
                for (long r = value; r != 0; ) {
                    long q = g / r;
                    long temp = g % r;
                    g = r;
                    r = temp;

                    long t = x - q * y;
                    x = y;
                    y = t;
                }
                assert g == 1;
                assert y == modulus() || y == -modulus();
                return normalize(x);
            }
        }
    }
