import sys

class NumberTheory:
    class Mod998:
        def __init__(self):
            self.modulus_value = 998244353
            self.factorial = [1]
            self.inv_factorial = [1]

        def modulus(self):
            return self.modulus_value

        def fact(self, n):
            while len(self.factorial) <= n:
                self.factorial.append(self.mult(self.factorial[-1], len(self.factorial)))
            return self.factorial[n]

        def fInv(self, n):
            last_idx = len(self.inv_factorial) - 1
            if last_idx < n:
                fInvArr = [0] * (n - last_idx)
                fInvArr[0] = self.inv(self.fact(n))
                for i in range(1, len(fInvArr)):
                    fInvArr[i] = self.mult(fInvArr[i - 1], n - i + 1)
                for i in reversed(range(len(fInvArr))):
                    self.inv_factorial.append(fInvArr[i])

        def ncr(self, n, r):
            if n < 0 or r < 0 or n < r:
                return 0
            return self.mult(self.fact(n), self.mult(self.fInv(r), self.fInv(n - r)))

        def smallInv(self, n):
            return self.mult(self.fInv(n), self.fact(n - 1))

        def normalize(self, x):
            m = self.modulus()
            x %= m
            if x < 0:
                x += m
            return x

        def add(self, a, b):
            res = a + b
            m = self.modulus()
            return res - m if res >= m else res

        def subtract(self, a, b):
            res = a - b
            m = self.modulus()
            return res + m if res < 0 else res

        def mult(self, a, b):
            return (a * b) % self.modulus()

        def inv(self, value):
            g, x, y = self.modulus(), 0, 1
            r = value
            while r != 0:
                q = g // r
                g, r = r, g % r
                t = x - q * y
                x, y = y, t
            assert g == 1
            assert y == self.modulus() or y == -self.modulus()
            return self.normalize(x)

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])

    mod = NumberTheory.Mod998()
    mod.fInv(n + m)

    phaseSize = 1
    p = 1
    i = 0
    while p != 0:
        p = mod.mult(mod.mult(p, n - i), mod.smallInv(n + m - i))
        phaseSize = mod.add(phaseSize, p)
        i += 1

    answer = 0
    for k in range(1, n + 1):
        numPhases = mod.mult(m + k, mod.smallInv(k))
        term = mod.mult(mod.ncr(n, k), mod.mult(numPhases, phaseSize))
        if k & 1:
            answer = mod.add(answer, term)
        else:
            answer = mod.subtract(answer, term)

    print(answer)

if __name__ == "__main__":
    main()

